{FileDialogInprocessSession session(Provider(old));Check(session.Prepare(decision,nullptr)==HRESULT_FROM_WIN32(ERROR_NOT_SUPPORTED)&&initialized==0,"old provider spy is rejected before Initialize");}
{FileDialogInprocessSession session(Provider(features));const auto hr=session.Prepare(decision,nullptr);Check(hr==S_OK&&initialized==1&&(captured&PULSE_PICKER_UI_V2_OPEN_MISSING_VALIDATED)&&(captured&PULSE_PICKER_UI_V2_OPEN_ALLOW_MISSING)&&!(captured&PULSE_PICKER_UI_V2_OPEN_SKIP_ACCESS_VALIDATION),"new provider receives explicit marker without skipping access");}
