Check(!MissingOpenOptionsSupported(allow,0,false,false),"old ABI invalid allow-only combination remains unsupported");Check(MissingOpenOptionsSupported(allow|validated,0,false,false),"new ABI marker explicitly admits validated missing Open");Check(MissingOpenOptionsSupported(allow|skip,0,false,false),"legacy explicit skip policy remains supported");Check(!MissingOpenOptionsSupported(validated,0,false,false)&&!MissingOpenOptionsSupported(allow|validated|skip,0,false,false)&&!MissingOpenOptionsSupported(allow|validated,FOS_CREATEPROMPT,false,false)&&!MissingOpenOptionsSupported(allow|validated,0,false,true),"inconsistent new ABI markers and Save are rejected");Check(!pulse::ipc::picker::remote::ConfigSupportedByPeer(allow|validated,0,features),"remote 0xff Open wire contract is not expanded");
